document.getElementById('investor-deck-submit-btn').addEventListener('click', function () {
    const form = document.getElementById('investor-deck-submit-btn').closest('.investor-deck-form');
    if (form) {
        const submitBtn = form.querySelector('.wpforms-form .wpforms-submit');
        if (submitBtn) {
            submitBtn.click();
        }
    }
});

