	document.addEventListener('click', function(e) {

		const hiddenField = document.querySelector('#wpforms-717-field_4');

		if (!hiddenField) {
			return;
		}

		const button = e.target.closest('.pricing__btn button');

		if (button) {
			hiddenField.value = 'Main Nav CTA Button';
			return;
		}

		const link = e.target.closest('.pricing__btn a');

		if (!link) {
			return;
		}

		 const slug =
        window.location.pathname.replace(/^\/|\/$/g, '') || 'home';

		console.log("Clicked link on slug:", slug);

		const values = {			
			'projects/cisco-project': 'Cisco Project Page',
			'investors': 'Investor Hub',
			'home': 'Homepage'
		};


		if (hiddenField) {
			hiddenField.value = values[slug] || 'Main Nav CTA Button';
		}

	});
